"""Weekly pilot metrics: parties logged per day and week-over-week growth."""
from collections import Counter

def weekly_growth(counts_by_week):
    """counts_by_week: list of parties per week, oldest first."""
    out = []
    for prev, cur in zip(counts_by_week, counts_by_week[1:]):
        out.append(None if prev == 0 else round((cur - prev) / prev * 100, 1))
    return out

if __name__ == "__main__":
    daily = Counter({"Mon": 22, "Tue": 18, "Wed": 25})
    print("Parties per day:", dict(daily))
    print("Week-over-week %:", weekly_growth([40, 46, 52]))
